const recentDuplicateOrder = `-- name: RecentDuplicateOrder :one
select o.reference, o.created_at
from orders o
where o.phone_e164 = $1::text
  and o.deleted_at is null
  and o.created_at > $2::timestamptz
  and ($3::uuid is null
       or exists (select 1 from order_items i where i.order_id = o.id and i.offer_id = $3::uuid))
order by o.created_at desc
limit 1
`

type RecentDuplicateOrderParams struct {
	PhoneE164 string
	Since     time.Time
	OfferID   uuid.NullUUID
}

type RecentDuplicateOrderRow struct {
	Reference string
	CreatedAt time.Time
}

// Duplicate guard: the latest order from this phone since @since, for the same
// offer (or any order when offer_id is null, e.g. a custom quantity).
func (q *Queries) RecentDuplicateOrder(ctx context.Context, arg RecentDuplicateOrderParams) (RecentDuplicateOrderRow, error) {
	row := q.db.QueryRow(ctx, recentDuplicateOrder, arg.PhoneE164, arg.Since, arg.OfferID)
	var i RecentDuplicateOrderRow
	err := row.Scan(&i.Reference, &i.CreatedAt)
	return i, err
}

