const searchOrders = `-- name: SearchOrders :many
select o.id, o.reference, o.customer_name, o.phone_e164, o.city, o.total, o.status,
       o.locale, o.seen_at, o.paid_at, o.created_at,
       (select coalesce(sum(i.quantity), 0) from order_items i where i.order_id = o.id)::int as item_count,
       count(*) over () as total_count
from orders o
where o.deleted_at is null
  and ($1::text is null
       or o.reference ilike '%' || $1::text || '%'
       or o.customer_name ilike '%' || $1::text || '%'
       or ($2::text is not null and o.phone_e164 like '%' || $2::text || '%'))
  and ($3::order_status is null or o.status = $3::order_status)
  and ($4::boolean is null or (o.paid_at is not null) = $4::boolean)
  and (not $5::boolean or o.seen_at is null)
  and ($6::text is null or o.city ilike '%' || $6::text || '%')
  and ($7::uuid is null
       or exists (select 1 from order_items i where i.order_id = o.id and i.offer_id = $7::uuid))
  and ($8::timestamptz is null or o.created_at >= $8::timestamptz)
  and ($9::timestamptz is null or o.created_at < $9::timestamptz)
order by
  case when $10::text = 'created_asc' then o.created_at end asc,
  case when $10::text = 'total_desc' then o.total end desc,
  case when $10::text = 'total_asc' then o.total end asc,
  case when $10::text = 'name_asc' then o.customer_name end asc,
  case when $10::text = 'name_desc' then o.customer_name end desc,
  case when $10::text = 'city_asc' then o.city end asc,
  case when $10::text = 'city_desc' then o.city end desc,
  case when $10::text = 'status_asc' then o.status end asc,
  case when $10::text = 'status_desc' then o.status end desc,
  o.created_at desc, o.number desc
limit $12::int offset $11::int
`

type SearchOrdersParams struct {
	Q          *string
	Phone      *string
	Status     *OrderStatus
	Paid       *bool
	UnseenOnly bool
	City       *string
	OfferID    uuid.NullUUID
	FromDate   *time.Time
	ToDate     *time.Time
	SortKey    string
	PageOffset int32
	PageSize   int32
}

type SearchOrdersRow struct {
	ID           uuid.UUID
	Reference    string
	CustomerName string
	PhoneE164    string
	City         string
	Total        decimal.Decimal
	Status       OrderStatus
	Locale       Locale
	SeenAt       *time.Time
	PaidAt       *time.Time
	CreatedAt    time.Time
	ItemCount    int32
	TotalCount   int64
}

// Fixed SQL with nullable filters. sort_key comes from a whitelist in Go and is
// mapped to fixed CASE branches here, never concatenated. q and city arrive
// with LIKE wildcards already stripped.
func (q *Queries) SearchOrders(ctx context.Context, arg SearchOrdersParams) ([]SearchOrdersRow, error) {
	rows, err := q.db.Query(ctx, searchOrders,
		arg.Q,
		arg.Phone,
		arg.Status,
		arg.Paid,
		arg.UnseenOnly,
		arg.City,
		arg.OfferID,
		arg.FromDate,
		arg.ToDate,
		arg.SortKey,
		arg.PageOffset,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchOrdersRow{}
	for rows.Next() {
		var i SearchOrdersRow
		if err := rows.Scan(
			&i.ID,
			&i.Reference,
			&i.CustomerName,
			&i.PhoneE164,
			&i.City,
			&i.Total,
			&i.Status,
			&i.Locale,
			&i.SeenAt,
			&i.PaidAt,
			&i.CreatedAt,
			&i.ItemCount,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

